void getNewFaces(int top, int south, int east, int dir, int& newTop, int& newSouth, int& newEast) {
    int north = 7 - south;
    int west = 7 - east;
    int bottom = 7 - top;

    if (dir == 0) { // north
        newTop = south;
        newSouth = bottom;
        newEast = east;
    } else if (dir == 1) { // east
        newTop = west;
        newSouth = south;
        newEast = top;
    } else if (dir == 2) { // south
        newTop = north;
        newSouth = top;
        newEast = east;
    } else { // west
        newTop = east;
        newSouth = south;
        newEast = bottom;
    }
}

