#include <bits/stdc++.h>
using namespace std;

struct State {
    int x, y, ori;
};

static const long long INF = (1LL << 60);

// Orientation represented by values on faces:
// top, bottom, north, south, east, west
struct Die {
    int t, b, n, s, e, w;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // Generate all 24 orientations of a die starting from:
    // top=1, south=2, east=3
    // opposite faces sum to 7
    Die start{1, 6, 5, 2, 3, 4};

    auto roll_north = [](const Die& d) -> Die {
        // move to north: top<-south, bottom<-north, north<-top, south<-bottom
        return Die{d.s, d.n, d.t, d.b, d.e, d.w};
    };
    auto roll_south = [](const Die& d) -> Die {
        return Die{d.n, d.s, d.b, d.t, d.e, d.w};
    };
    auto roll_east = [](const Die& d) -> Die {
        return Die{d.w, d.e, d.n, d.s, d.t, d.b};
    };
    auto roll_west = [](const Die& d) -> Die {
        return Die{d.e, d.w, d.n, d.s, d.b, d.t};
    };

    vector<Die> oriList;
    map<array<int,6>, int> id;
    queue<Die> q;
    auto keyOf = [](const Die& d) {
        return array<int,6>{d.t,d.b,d.n,d.s,d.e,d.w};
    };

    q.push(start);
    id[keyOf(start)] = 0;
    oriList.push_back(start);

    while (!q.empty()) {
        Die cur = q.front(); q.pop();
        vector<Die> nxts = {
            roll_north(cur), roll_south(cur), roll_east(cur), roll_west(cur)
        };
        for (auto &nd : nxts) {
            auto k = keyOf(nd);
            if (!id.count(k)) {
                int nid = (int)oriList.size();
                id[k] = nid;
                oriList.push_back(nd);
                q.push(nd);
            }
        }
    }

    // transitions[ori][dir]
    // dir: 0=north,1=south,2=west,3=east
    int transitions[24][4];
    for (int i = 0; i < 24; ++i) {
        transitions[i][0] = id[keyOf(roll_north(oriList[i]))];
        transitions[i][1] = id[keyOf(roll_south(oriList[i]))];
        transitions[i][2] = id[keyOf(roll_west(oriList[i]))];
        transitions[i][3] = id[keyOf(roll_east(oriList[i]))];
    }

    int h, w;
    while (cin >> h >> w, h || w) {
        vector<vector<int>> a(h, vector<int>(w));
        for (int i = 0; i < h; ++i)
            for (int j = 0; j < w; ++j)
                cin >> a[i][j];

        int sy, sx, gy, gx;
        cin >> sy >> sx >> gy >> gx;
        --sy; --sx; --gy; --gx;

        // Dijkstra on (y, x, orientation)
        int N = h * w * 24;
        vector<long long> dist(N, INF);

        auto idx = [&](int y, int x, int o) {
            return (y * w + x) * 24 + o;
        };

        priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<pair<long long,int>>> pq;
        int startOri = 0; // generated first orientation is the initial one
        dist[idx(sy, sx, startOri)] = 0;
        pq.push({0, idx(sy, sx, startOri)});

        int dy[4] = {-1, 1, 0, 0};
        int dx[4] = {0, 0, -1, 1};

        while (!pq.empty()) {
            auto [cd, v] = pq.top();
            pq.pop();
            if (cd != dist[v]) continue;

            int o = v % 24;
            int cell = v / 24;
            int y = cell / w;
            int x = cell % w;

            for (int dir = 0; dir < 4; ++dir) {
                int ny = y + dy[dir];
                int nx = x + dx[dir];
                if (ny < 0 || ny >= h || nx < 0 || nx >= w) continue;

                int no = transitions[o][dir];
                int bottom = oriList[no].b;
                long long nd = cd + a[y][x] * 1LL * bottom;

                int nv = idx(ny, nx, no);
                if (nd < dist[nv]) {
                    dist[nv] = nd;
                    pq.push({nd, nv});
                }
            }
        }

        long long ans = INF;
        for (int o = 0; o < 24; ++o) {
            ans = min(ans, dist[idx(gy, gx, o)]);
        }

        cout << ans << '\n';
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
