#define MAXH 32
#define MAXW 32
#define DIRS 4
#define INF 1000000000

// Directions: 0=north, 1=east, 2=south, 3=west
int dx[4] = {-1, 0, 1, 0};
int dy[4] = {0, 1, 0, -1};

// Die state: top, south, east
// We encode state as index: top*36 + south*6 + east (each 1..6)
// But we can also store as 3 ints.
typedef struct {
    int top, south, east;
} DieState;

// Given top, south, east, return bottom (opposite of top)
int bottom(int top) {
    return 7 - top;
}

// Roll die in direction dir (0=N,1=E,2=S,3=W)
DieState roll(DieState s, int dir) {
    DieState ns;
    int top = s.top, south = s.south, east = s.east;
    int north = 7 - south;
    int west = 7 - east;
    int bottom = 7 - top;

    switch(dir) {
        case 0: // north: top->south, south->bottom, bottom->north, north->top
            ns.top = south;
            ns.south = bottom;
            ns.east = east;
            break;
        case 1: // east: top->west, west->bottom, bottom->east, east->top
            ns.top = west;
            ns.south = south;
            ns.east = top;
            break;
        case 2: // south: top->north, north->bottom, bottom->south, south->top
            ns.top = north;
            ns.south = top;
            ns.east = east;
            break;
        case 3: // west: top->east, east->bottom, bottom->west, west->top
            ns.top = east;
            ns.south = south;
            ns.east = bottom;
            break;
    }
    return ns;
}

// For Dijkstra, we need to map (r,c,state) to an index
// state index = (top-1)*36 + (south-1)*6 + (east-1)
int stateIndex(DieState s) {
    return (s.top-1)*36 + (south-1)*6 + (east-1);
}

int main() {
    int h, w;
    int grid[MAXH][MAXW];
    int dist[MAXH][MAXW][216]; // 216 = 6*6*6
    int visited[MAXH][MAXW][216];
    int sr, sc, dr, dc;
    int caseNum = 0;

    while(1) {
        scanf("%d %d", &h, &w);
        if(h == 0 && w == 0) break;
        caseNum++;

        for(int i = 0; i < h; i++) {
            for(int j = 0; j < w; j++) {
                scanf("%d", &grid[i][j]);
            }
        }
        scanf("%d %d %d %d", &sr, &sc, &dr, &dc);

        // Initialize distances
        for(int i = 0; i < h; i++) {
            for(int j = 0; j < w; j++) {
                for(int k = 0; k < 216; k++) {
                    dist[i][j][k] = INF;
                    visited[i][j][k] = 0;
                }
            }
        }

        // Starting state: top=1, south=2, east=3
        DieState startState = {1, 2, 3};
        int startIdx = stateIndex(startState);
        // Penalty at start: grid[sr][sc] * bottom(1) = grid[sr][sc] * 6
        dist[sr][sc][startIdx] = grid[sr][sc] * bottom(1);

        // Simple Dijkstra using array for priority (grid small, states limited)
        // We'll just scan for minimum each iteration
        while(1) {
            int minDist = INF;
            int minR = -1, minC = -1, minS = -1;
            for(int i = 0; i < h; i++) {
                for(int j = 0; j < w; j++) {
                    for(int k = 0; k < 216; k++) {
                        if(!visited[i][j][k] && dist[i][j][k] < minDist) {
                            minDist = dist[i][j][k];
                            minR = i; minC = j; minS = k;
                        }
                    }
                }
            }
            if(minR == -1) break; // no more reachable states
            visited[minR][minC][minS] = 1;

            // If we reached destination (any state), we can break early
            // but must check all states at destination? Actually we need min over all states at dest
            // So continue until all are processed or we can break when we pop destination?
            // For correctness, we continue. But we can break if minR==dr && minC==dc because Dijkstra guarantees first time we pop destination is optimal.
            if(minR == dr && minC == dc) {
                printf("Case %d: %d\n", caseNum, minDist);
                break;
            }

            // Decode state
            int top = (minS / 36) + 1;
            int rem = minS % 36;
            int south = (rem / 6) + 1;
            int east = (rem % 6) + 1;
            DieState cur = {top, south, east};

            // Try moving in 4 directions
            for(int d = 0; d < 4; d++) {
                int nr = minR + dx[d];
                int nc = minC + dy[d];
                if(nr < 0 || nr >= h || nc < 0 || nc >= w) continue;
                DieState ns = roll(cur, d);
                int nsIdx = stateIndex(ns);
                int penalty = grid[nr][nc] * bottom(ns.top);
                int nd = minDist + penalty;
                if(nd < dist[nr][nc][nsIdx]) {
                    dist[nr][nc][nsIdx] = nd;
                }
            }
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAXH 35
#define MAXW 35
#define MAXS 24
#define INF  ((long long)4e18)

typedef struct {
    int top, bottom, north, south, west, east;
} Dice;

typedef struct {
    int x, y, s;
    long long d;
} Node;

static int h, w;
static int grid[MAXH][MAXW];
static int sx, sy, tx, ty;

/* 24 dice orientations */
static Dice states[24];
static int state_cnt;

/* transitions: 0=N,1=S,2=W,3=E */
static int trans[MAXS][4];

/* ---------- Dice operations ---------- */
static Dice roll_north(Dice a) {
    Dice b;
    b.top = a.south;
    b.bottom = a.north;
    b.north = a.top;
    b.south = a.bottom;
    b.west = a.west;
    b.east = a.east;
    return b;
}

static Dice roll_south(Dice a) {
    Dice b;
    b.top = a.north;
    b.bottom = a.south;
    b.north = a.bottom;
    b.south = a.top;
    b.west = a.west;
    b.east = a.east;
    return b;
}

static Dice roll_west(Dice a) {
    Dice b;
    b.top = a.east;
    b.bottom = a.west;
    b.north = a.north;
    b.south = a.south;
    b.west = a.top;
    b.east = a.bottom;
    return b;
}

static Dice roll_east(Dice a) {
    Dice b;
    b.top = a.west;
    b.bottom = a.east;
    b.north = a.north;
    b.south = a.south;
    b.west = a.bottom;
    b.east = a.top;
    return b;
}

static int same_dice(Dice a, Dice b) {
    return a.top == b.top && a.bottom == b.bottom &&
           a.north == b.north && a.south == b.south &&
           a.west == b.west && a.east == b.east;
}

static int find_state(Dice d) {
    for (int i = 0; i < state_cnt; i++) {
        if (same_dice(states[i], d)) return i;
    }
    return -1;
}

static void build_states(void) {
    state_cnt = 0;
    Dice init = {1, 6, 5, 2, 4, 3}; /* top=1, south=2, east=3 */
    Dice queue[64];
    int head = 0, tail = 0;
    queue[tail++] = init;
    states[state_cnt++] = init;

    while (head < tail) {
        Dice cur = queue[head++];
        Dice nxt[4];
        nxt[0] = roll_north(cur);
        nxt[1] = roll_south(cur);
        nxt[2] = roll_west(cur);
        nxt[3] = roll_east(cur);
        for (int k = 0; k < 4; k++) {
            if (find_state(nxt[k]) == -1) {
                states[state_cnt++] = nxt[k];
                queue[tail++] = nxt[k];
            }
        }
    }

    for (int i = 0; i < state_cnt; i++) {
        trans[i][0] = find_state(roll_north(states[i]));
        trans[i][1] = find_state(roll_south(states[i]));
        trans[i][2] = find_state(roll_west(states[i]));
        trans[i][3] = find_state(roll_east(states[i]));
    }
}

/* ---------- Min-heap for Dijkstra ---------- */
typedef struct {
    Node *a;
    int size, cap;
} Heap;

static void heap_init(Heap *h, int cap) {
    h->a = (Node *)malloc(sizeof(Node) * cap);
    h->size = 0;
    h->cap = cap;
}

static void heap_push(Heap *h, Node v) {
    if (h->size >= h->cap) {
        h->cap *= 2;
        h->a = (Node *)realloc(h->a, sizeof(Node) * h->cap);
    }
    int i = h->size++;
    while (i > 0) {
        int p = (i - 1) >> 1;
        if (h->a[p].d <= v.d) break;
        h->a[i] = h->a[p];
        i = p;
    }
    h->a[i] = v;
}

static Node heap_pop(Heap *h) {
    Node ret = h->a[0];
    Node v = h->a[--h->size];
    int i = 0;
    while (1) {
        int l = i * 2 + 1, r = l + 1, m;
        if (l >= h->size) break;
        m = l;
        if (r < h->size && h->a[r].d < h->a[l].d) m = r;
        if (h->a[m].d >= v.d) break;
        h->a[i] = h->a[m];
        i = m;
    }
    h->a[i] = v;
    return ret;
}

static int heap_empty(Heap *h) {
    return h->size == 0;
}

/* ---------- Solve one case ---------- */
static long long solve_case(void) {
    static long long dist[MAXH][MAXW][MAXS];
    for (int i = 0; i < h; i++)
        for (int j = 0; j < w; j++)
            for (int s = 0; s < state_cnt; s++)
                dist[i][j][s] = INF;

    int init_state = find_state((Dice){1, 6, 5, 2, 4, 3});

    Heap pq;
    heap_init(&pq, 1024);
    dist[sx][sy][init_state] = 0;
    heap_push(&pq, (Node){sx, sy, init_state, 0});

    int dx[4] = {-1, 1, 0, 0};
    int dy[4] = {0, 0, -1, 1};

    while (!heap_empty(&pq)) {
        Node cur = heap_pop(&pq);
        if (cur.d != dist[cur.x][cur.y][cur.s]) continue;

        for (int dir = 0; dir < 4; dir++) {
            int nx = cur.x + dx[dir];
            int ny = cur.y + dy[dir];
            if (nx < 0 || nx >= h || ny < 0 || ny >= w) continue;

            int ns = trans[cur.s][dir];
            int bottom = states[ns].bottom;
            long long nd = cur.d + llabs((long long)grid[cur.x][cur.y] - bottom);

            if (nd < dist[nx][ny][ns]) {
                dist[nx][ny][ns] = nd;
                heap_push(&pq, (Node){nx, ny, ns, nd});
            }
        }
    }

    long long ans = INF;
    for (int s = 0; s < state_cnt; s++) {
        if (dist[tx][ty][s] < ans) ans = dist[tx][ty][s];
    }

    free(pq.a);
    return ans;
}

int main(void) {
    build_states();

    while (scanf("%d %d", &h, &w) == 2) {
        if (h == 0 && w == 0) break;

        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                scanf("%d", &grid[i][j]);
            }
        }

        scanf("%d %d %d %d", &sx, &sy, &tx, &ty);

        /* assume coordinates are 1-based in input */
        sx--; sy--; tx--; ty--;

        printf("%lld\n", solve_case());
    }

    return 0;
}

import heapq
import sys

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    while True:
        h = int(input_data[idx]); w = int(input_data[idx+1]); idx += 2
        if h == 0 and w == 0:
            break
        grid = []
        for i in range(h):
            row = list(map(int, input_data[idx:idx+w]))
            idx += w
            grid.append(row)
        sr = int(input_data[idx])-1; sc = int(input_data[idx+1])-1; idx += 2
        dr = int(input_data[idx])-1; dc = int(input_data[idx+1])-1; idx += 2

        # Die state: (top, bottom, north, south, east, west)
        init_die = (1, 6, 5, 2, 3, 4)

        def roll(die, direction):
            top, bot, north, south, east, west = die
            if direction == 'S':  # move south
                return (north, south, bot, top, east, west)
            elif direction == 'N':  # move north
                return (south, north, top, bot, east, west)
            elif direction == 'E':  # move east
                return (west, east, north, south, top, bot)
            elif direction == 'W':  # move west
                return (east, west, north, south, bot, top)

        # Dijkstra: state = (cost, row, col, die)
        INF = float('inf')
        dist = {}
        heap = [(0, sr, sc, init_die)]

        while heap:
            cost, r, c, die = heapq.heappop(heap)

            if (r, c, die) in dist:
                continue
            dist[(r, c, die)] = cost

            if r == dr and c == dc:
                print(cost)
                break

            # Try all 4 directions
            for direction, dr2, dc2 in [('S', r+1, c), ('N', r-1, c), ('E', r, c+1), ('W', r, c-1)]:
                if 0 <= dr2 < h and 0 <= dc2 < w:
                    new_die = roll(die, direction)
                    # penalty = current cell value * bottom of die after rolling
