import java.io.*;
import java.util.*;

public class Main {
    static final int[] dr = {0, 1, 0, -1}; // east, south, west, north
    static final int[] dc = {1, 0, -1, 0};

    // die faces: top, bottom, north, south, east, west
    // initial: top=1, south=2, east=3
    // We'll encode state as (top, south, east) and derive others.

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);

        while (true) {
            String[] parts = br.readLine().split(" ");
            int h = Integer.parseInt(parts[0]);
            int w = Integer.parseInt(parts[1]);
            if (h == 0 && w == 0) break;

            int[][] grid = new int[h][w];
            for (int i = 0; i < h; i++) {
                StringTokenizer st = new StringTokenizer(br.readLine());
                for (int j = 0; j < w; j++) {
                    grid[i][j] = Integer.parseInt(st.nextToken());
                }
            }

            String[] startParts = br.readLine().split(" ");
            int sr = Integer.parseInt(startParts[0]);
            int sc = Integer.parseInt(startParts[1]);
            String[] destParts = br.readLine().split(" ");
            int drc = Integer.parseInt(destParts[0]);
            int dcc = Integer.parseInt(destParts[1]);

            // Dijkstra: state = (r, c, top, south, east)
            // We'll map each state to cost
            // Number of die states: top (1..6), south (1..6) but must be consistent
            // Actually we can encode as die orientation index 0..23
            // But simpler: we store dist[r][c][top][south] (east derived)
            // top and south determine east uniquely (since opposite faces sum to 7)
            // However not all pairs (top,south) are valid: top != south, top != 7-south
            // We'll just use a 3D array: dist[r][c][dieState] where dieState 0..23
            // Precompute all 24 orientations.

            int[][][] dieStates = generateDieStates();
            // dieStates[k] = {top, bottom, north, south, east, west}

            // Map (top, south, east) -> state index
            Map<String, Integer> stateMap = new HashMap<>();
            for (int i = 0; i < 24; i++) {
                int[] d = dieStates[i];
                stateMap.put(d[0] + "," + d[3] + "," + d[4], i);
                // top, south, east
            }

            // Initial die: top=1, south=2, east=3
            int startState = stateMap.get("1,2,3");

            long[][][] dist = new long[h][w][24];
            for (int i = 0; i < h; i++)
                for (int j = 0; j < w; j++)
                    Arrays.fill(dist[i][j], Long.MAX_VALUE);

            PriorityQueue<State> pq = new PriorityQueue<>();
            dist[sr][sc][startState] = 0;
            pq.offer(new State(sr, sc, startState, 0));

            long answer = Long.MAX_VALUE;

            while (!pq.isEmpty()) {
                State cur = pq.poll();
                int r = cur.r, c = cur.c, s = cur.s;
                long d = cur.dist;
                if (d != dist[r][c][s]) continue;

                if (r == drc && c == dcc) {
                    answer = Math.min(answer, d);
                    // We can't break because there might be cheaper path with different die orientation
                    // But since Dijkstra, first time we pop destination it's minimal for that orientation
                    // But we need min over all orientations at destination, so continue
                    // Actually we can break if we know no better path possible, but safe to continue
                }

                int[] die = dieStates[s];
                int top = die[0];
                int bottom = die[1];
                int north = die[2];
                int south = die[3];
                int east = die[4];
                int west = die[5];

                for (int dir = 0; dir < 4; dir++) {
                    int nr = r + dr[dir];
                    int nc = c + dc[dir];
                    if (nr < 0 || nr >= h || nc < 0 || nc >= w) continue;

                    // Roll die in direction
                    int[] newDie = rollDie(top, south, east, dir);
                    int newTop = newDie[0];
                    int newSouth = newDie[1];
                    int newEast = newDie[2];
                    int newBottom = newDie[3];

                    int newState = stateMap.get(newTop + "," + newSouth + "," + newEast);

                    long penalty = grid[nr][nc] * newBottom;
                    long nd = d + penalty;
                    if (nd < dist[nr][nc][newState]) {
                        dist[nr][nc][newState] = nd;
                        pq.offer(new State(nr, nc, newState, nd));
                    }
                }
            }

            pw.println(answer);
        }

        pw.flush();
        pw.close();
        br.close();
    }

    static int[][] generateDieStates() {
        // All 24 orientations: start with standard die (top=1, bottom=6, north=5, south=2, east=3, west=4)
        // Then rotate
        int[][] states = new int[24][6];
        int idx = 0;
        // fixed die: top,bottom,north,south,east,west
        int[] base = {1,6,5,2,3,4};
        // Generate all rotations
        for (int t = 0; t < 6; t++) {
            // rotate so that base[t] becomes top
            int[] die = new int[6];
            System.arraycopy(base, 0, die, 0, 6);
            // bring face t to top
            if (t == 0) {} // already top
            else if (t == 1) { // bottom to top -> rotate around north-south axis
                // top<->bottom, north/south unchanged, east/west flipped? Actually rotation 180 around north-south
                die = rotateNS(die);
            } else if (t == 2) { // north to top -> rotate around east-west axis
                die = rotateEW(die);
                die = rotateEW(die);
                die = rotateEW(die);
            } else if (t == 3) { // south to top
                die = rotateEW(die);
            } else if (t == 4) { // east to top -> rotate around north-south axis? Actually rotate around vertical axis then tilt
                die = rotateNS(die);
                die = rotateNS(die);
                die = rotateNS(die);
            } else if (t == 5) { // west to top
                die = rotateNS(die);
            }
            // Now we have a die with a given top. Generate 4 rotations keeping top fixed
            for (int r = 0; r < 4; r++) {
                states[idx++] = die.clone();
                die = rotateVertical(die); // rotate around vertical axis (top-bottom)
            }
        }
        return states;
    }

    static int[] rotateNS(int[] die) {
        // rotate 90 degrees around north-south axis (north stays, south stays)
        // top -> east, east -> bottom, bottom -> west, west -> top
        int[] nd = new int[6];
        nd[0] = die[4]; // top = east
        nd[1] = die[5]; // bottom = west
        nd[2] = die[2]; // north unchanged
        nd[3] = die[3]; // south unchanged
        nd[4] = die[1]; // east = bottom
        nd[5] = die[0]; // west = top
        return nd;
    }

    static int[] rotateEW(int[] die) {
        // rotate 90 degrees around east-west axis (east stays, west stays)
        // top -> north, north -> bottom, bottom -> south, south -> top
        int[] nd = new int[6];
        nd[0] = die[2]; // top = north
        nd[1] = die[3]; // bottom = south
        nd[2] = die[1]; // north = bottom
        nd[3] = die[0]; // south = top
        nd[4] = die[4]; // east unchanged
        nd[5] = die[5]; // west unchanged
        return nd;
    }

    static int[] rotateVertical(int[] die) {
        // rotate 90 degrees clockwise around vertical axis (top-bottom)
        // north -> east, east -> south, south -> west, west -> north
        int[] nd = new int[6];
        nd[0] = die[0]; // top
        nd[1] = die[1]; // bottom
        nd[2] = die[5]; // north = west
        nd[3] = die[4]; // south = east
        nd[4] = die[2]; // east = north
        nd[5] = die[3]; // west = south
        return nd;
    }

    static int[] rollDie(int top, int south, int east, int dir) {
        // dir: 0=east, 1=south, 2=west, 3=north
        // Returns {newTop, newSouth, newEast, newBottom}
        int bottom = 7 - top;
        int north = 7 - south;
        int west = 7 - east;

        int newTop, newSouth, newEast, newBottom;
        if (dir == 0) { // roll east: top->west, east->top, bottom->east, west->bottom
            newTop = west;
            newSouth = south;
            newEast = top;
            newBottom = east;
        } else if (dir == 1) { // roll south: top->north, south->top, bottom->south, north->bottom
            newTop = north;
            newSouth = top;
            newEast = east;
            newBottom = south;
        } else if (dir == 2) { // roll west: top->east, west->top, bottom->west, east->bottom
            newTop = east;
            newSouth = south;
            newEast = bottom;
            newBottom = west;
        } else { // dir == 3, roll north: top->south, north->top, bottom->north, south->bottom
            newTop = south;
            newSouth = bottom;
            newEast = east;
            newBottom = north;
        }
        return new int[]{newTop, newSouth, newEast, newBottom};
    }

    static class State implements Comparable<State> {
        int r, c, s;
        long dist;
        State(int r, int c, int s, long dist) {
            this.r = r; this.c = c; this.s = s; this.dist = dist;
        }
        public int compareTo(State o) {
            return Long.compare(this.dist, o.dist);
        }
    }
}

