import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class State implements Comparable<State> {
        long dist;
        int r, c, ori;

        State(long dist, int r, int c, int ori) {
            this.dist = dist;
            this.r = r;
            this.c = c;
            this.ori = ori;
        }

        public int compareTo(State other) {
            return Long.compare(this.dist, other.dist);
        }
    }

    // orientation represented by top, south, east
    static class Ori {
        int top, south, east;
        Ori(int t, int s, int e) {
            top = t; south = s; east = e;
        }
    }

    static int opposite(int x) {
        return 7 - x;
    }

    static Ori rollNorth(Ori o) {
        int top = o.south;
        int south = opposite(o.top);
        int east = o.east;
        return new Ori(top, south, east);
    }

    static Ori rollSouth(Ori o) {
        int top = opposite(o.south);
        int south = o.top;
        int east = o.east;
        return new Ori(top, south, east);
    }

    static Ori rollEast(Ori o) {
        int top = opposite(o.east);
        int south = o.south;
        int east = o.top;
        return new Ori(top, south, east);
    }

    static Ori rollWest(Ori o) {
        int top = o.east;
        int south = o.south;
        int east = opposite(o.top);
        return new Ori(top, south, east);
    }

    static int encode(Ori o) {
        return (o.top - 1) * 36 + (o.south - 1) * 6 + (o.east - 1);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        // Build all 24 valid orientations and transitions
        ArrayList<Ori> list = new ArrayList<>();
        HashMap<Integer, Integer> idMap = new HashMap<>();
        Queue<Ori> q = new ArrayDeque<>();

        Ori startOri = new Ori(1, 2, 3);
        q.add(startOri);
        idMap.put(encode(startOri), 0);
        list.add(startOri);

        while (!q.isEmpty()) {
            Ori cur = q.poll();
            Ori[] nexts = {rollNorth(cur), rollSouth(cur), rollEast(cur), rollWest(cur)};
            for (Ori nx : nexts) {
                int code = encode(nx);
                if (!idMap.containsKey(code)) {
                    idMap.put(code, list.size());
                    list.add(nx);
                    q.add(nx);
                }
            }
        }

        int ORI = list.size(); // should be 24
        int[][] trans = new int[ORI][4]; // 0=N,1=S,2=W,3=E
        int[] bottom = new int[ORI];
        for (int i = 0; i < ORI; i++) {
            Ori o = list.get(i);
            bottom[i] = opposite(o.top);
            trans[i][0] = idMap.get(encode(rollNorth(o)));
            trans[i][1] = idMap.get(encode(rollSouth(o)));
            trans[i][2] = idMap.get(encode(rollWest(o)));
            trans[i][3] = idMap.get(encode(rollEast(o)));
        }

        int startOriId = idMap.get(encode(startOri));

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (true) {
            int h = fs.nextInt();
            int w = fs.nextInt();
            if (h == 0 && w == 0) break;

            int[][] a = new int[h][w];
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    a[i][j] = fs.nextInt();
                }
            }

            int sr = fs.nextInt() - 1;
            int sc = fs.nextInt() - 1;
            int tr = fs.nextInt() - 1;
            int tc = fs.nextInt() - 1;

            long INF = Long.MAX_VALUE / 4;
            long[][][] dist = new long[h][w][ORI];
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    Arrays.fill(dist[i][j], INF);
                }
            }

            PriorityQueue<State> pq = new PriorityQueue<>();
            dist[sr][sc][startOriId] = 0;
            pq.add(new State(0, sr, sc, startOriId));

            long ans = -1;

            while (!pq.isEmpty()) {
                State cur = pq.poll();
                if (cur.dist != dist[cur.r][cur.c][cur.ori]) continue;

                if (cur.r == tr && cur.c == tc) {
                    ans = cur.dist;
                    break;
                }

                for (int d = 0; d < 4; d++) {
                    int nr = cur.r + dr[d];
                    int nc = cur.c + dc[d];
                    if (nr < 0 || nr >= h || nc < 0 || nc >= w) continue;

                    int no = trans[cur.ori][d];
                    long nd = cur.dist + (long) a[cur.r][cur.c] * bottom[no];
                    if (nd < dist[nr][nc][no]) {
                        dist[nr][nc][no] = nd;
                        pq.add(new State(nd, nr, nc, no));
                    }
                }
            }

            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }
}
